// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @notice Yield-bearing single-asset vault.
contract Vault {
    IERC20 public immutable asset;
    uint256 public totalShares;
    mapping(address => uint256) public sharesOf;

    event Deposit(address indexed user, uint256 amount, uint256 shares);

    error InsufficientBalance(uint256 needed, uint256 actual);

    constructor(IERC20 _asset) {
        asset = _asset;
    }

    function deposit(uint256 amount) external returns (uint256 shares) {
        uint256 supply = totalShares;
        uint256 reserves = asset.balanceOf(address(this));
        shares = supply == 0 ? amount : (amount * supply) / reserves;
        require(shares > 0, "zero shares");
        totalShares = supply + shares;
        sharesOf[msg.sender] += shares;
        bool ok = asset.transferFrom(msg.sender, address(this), amount);
        if (!ok) revert InsufficientBalance(amount, reserves);
        emit Deposit(msg.sender, amount, shares);
    }
}
